import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useFormContext } from '../context/FormContext';
import { validateCareer } from '../utils/validation';
import TextInput from '../components/common/TextInput';
import YearMonthInput from '../components/common/YearMonthInput';
import StepIndicator from '../components/common/StepIndicator';
import ProgressBar from '../components/common/ProgressBar';
import StepNavigation from '../components/common/StepNavigation';
import './StepPage.css';

/**
 * ステップ6 - 経歴画面
 */
function CareerPage() {
  const navigate = useNavigate();
  const { formData: contextData, updateCareer } = useFormContext();
  const [formData, setFormData] = useState(contextData.career);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    setFormData(contextData.career);
  }, [contextData.career]);

  const handleChange = (event) => {
    const { name, value } = event.target;
    const newFormData = { ...formData, [name]: value };
    setFormData(newFormData);
    updateCareer(newFormData);
    if (errors[name]) {
      setErrors((prev) => ({ ...prev, [name]: '' }));
    }
  };

  const handlePrev = () => {
    navigate('/step/5');
  };

  const handleNext = () => {
    const result = validateCareer(formData);
    if (!result.isValid) {
      setErrors(result.errors);
      return;
    }
    navigate('/step/7');
  };

  const handlePreview = () => {
    navigate('/preview');
  };

  return (
    <div className="step-page">
      <StepIndicator currentStep={6} />
      <ProgressBar currentStep={6} />

      <div className="step-page-content">
        <h2 className="step-page-title">経歴</h2>

        <div className="form-section">
          <p className="guide-text">
            過去のキャリア（所属会社や働き方）を入力してください。
            転職活動時にあなたの経験を伝える重要な情報となります。
          </p>
        </div>

        <div className="form-section">
          <h3 className="form-section-title">期間</h3>
          <div className="form-row form-row--align-center">
            <YearMonthInput
              name="startPeriod"
              value={formData.startPeriod}
              onChange={handleChange}
              error={errors.startPeriod}
            />
            <span className="period-separator">〜</span>
            <YearMonthInput
              name="endPeriod"
              value={formData.endPeriod}
              onChange={handleChange}
              error={errors.endPeriod}
            />
          </div>
        </div>

        <div className="form-section">
          <h3 className="form-section-title">職歴</h3>
          <TextInput
            name="company"
            value={formData.company}
            onChange={handleChange}
            placeholder="例：株式会社ライズフォース、フリーランス"
            error={errors.company}
          />
        </div>
      </div>

      <StepNavigation
        currentStep={6}
        onPrev={handlePrev}
        onNext={handleNext}
        onPreview={handlePreview}
      />
    </div>
  );
}

export default CareerPage;
